import { LightningElement, track } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import getConnections from '@salesforce/apex/RlyReleaseController.getConnections';
import testConnection from '@salesforce/apex/RlyReleaseController.testConnection';
import saveConnection from '@salesforce/apex/RlyReleaseController.saveConnection';
import migrateConnections from '@salesforce/apex/RlyReleaseController.migrateConnections';
import getChanges from '@salesforce/apex/RlyReleaseController.getChanges';
import compareChanges from '@salesforce/apex/RlyReleaseController.compareChanges';
import getDeletions from '@salesforce/apex/RlyReleaseController.getDeletions';
import getBranches from '@salesforce/apex/RlyReleaseController.getBranches';
import getSources from '@salesforce/apex/RlyReleaseController.getSources';
import compareBranch from '@salesforce/apex/RlyReleaseController.compareBranch';
import raiseRequest from '@salesforce/apex/RlyReleaseController.raiseRequest';
import startPipeline from '@salesforce/apex/RlyReleaseController.startPipeline';
import { buildDiff, sideBySide } from 'c/rlyDiff';

const BRANCH_RE = /^(feature|bugfix|hotfix)\/[a-z0-9._-]{1,100}$/;
const CODE_TYPES = ['ApexClass', 'ApexTrigger', 'ApexPage', 'ApexComponent', 'LightningComponentBundle', 'AuraDefinitionBundle'];
const PAGE_SIZE = 50;
const COMPARE_BATCH = 10;

const TYPE_INFO = {
    ApexClass: ['Apex class', 'Code'], ApexTrigger: ['Apex trigger', 'Code'], ApexPage: ['Visualforce page', 'Code'],
    ApexComponent: ['Visualforce component', 'Code'], LightningComponentBundle: ['Lightning web component', 'Code'],
    AuraDefinitionBundle: ['Aura component', 'Code'], Flow: ['Flow', 'Automation'], CustomObject: ['Custom object', 'Data model'],
    CustomField: ['Custom field', 'Data model'], ValidationRule: ['Validation rule', 'Data model'], RecordType: ['Record type', 'Data model'],
    GlobalValueSet: ['Global value set', 'Data model'], Layout: ['Page layout', 'Access and UI'], FlexiPage: ['Lightning page', 'Access and UI'],
    PermissionSet: ['Permission set', 'Access and UI'], PermissionSetGroup: ['Permission set group', 'Access and UI'],
    CustomTab: ['Tab', 'Access and UI'], QuickAction: ['Quick action', 'Access and UI'], StaticResource: ['Static resource', 'Other'],
    CustomLabel: ['Custom label', 'Other'], EmailTemplate: ['Email template', 'Other'], CustomMetadata: ['Custom metadata record', 'Other'],
    ListView: ['List view', 'Access and UI'], Profile: ['Profile', 'Access and UI'], CustomApplication: ['App', 'Access and UI'],
    Report: ['Report', 'Other'], Dashboard: ['Dashboard', 'Other'], NamedCredential: ['Named credential', 'Other'],
    RemoteSiteSetting: ['Remote site setting', 'Other']
};
const GROUP_ORDER = ['Code', 'Automation', 'Data model', 'Access and UI', 'Other'];
const DETECTABLE = ['ApexClass', 'ApexTrigger', 'ApexPage', 'ApexComponent', 'LightningComponentBundle', 'AuraDefinitionBundle', 'Flow',
    'CustomObject', 'CustomField', 'Layout', 'ValidationRule', 'RecordType', 'PermissionSet', 'PermissionSetGroup', 'CustomTab',
    'FlexiPage', 'StaticResource', 'CustomLabel', 'QuickAction', 'GlobalValueSet', 'EmailTemplate'];
const MANUAL_TYPES = [...DETECTABLE, 'CustomMetadata', 'ListView', 'Profile', 'CustomApplication', 'Report', 'Dashboard', 'NamedCredential', 'RemoteSiteSetting'];

const STATUS = {
    New: { label: 'New', cls: 'rr-badge rr-badge-new', help: 'Not in the target yet: it will be created.' },
    Different: { label: 'Different', cls: 'rr-badge rr-badge-diff', help: 'In the target with other content: it will be overwritten.' },
    Same: { label: 'Same as target', cls: 'rr-badge rr-badge-same', help: 'Already identical in the target.' },
    Exists: { label: 'In target', cls: 'rr-badge rr-badge-exists', help: 'In the target. XML types are compared line by line in the pull request.' },
    Deleted: { label: 'Only in target', cls: 'rr-badge rr-badge-del', help: 'Deleted here, still in the target: selecting it deletes it there.' },
    Error: { label: 'Not compared', cls: 'rr-badge rr-badge-same', help: 'The comparison failed for this item.' }
};

const TYPE_OPTIONS = [
    { label: 'GitHub', value: 'GitHub' },
    { label: 'GitLab', value: 'GitLab' },
    { label: 'Bitbucket', value: 'Bitbucket' },
    { label: 'Azure DevOps', value: 'AzureDevOps' },
    { label: 'DevOps Center', value: 'DevOpsCenter' }
];
const TYPE_LABEL = { GitHub: 'GitHub', GitLab: 'GitLab', Bitbucket: 'Bitbucket', AzureDevOps: 'Azure DevOps', DevOpsCenter: 'DevOps Center' };
const GIT_TYPES = ['GitHub', 'GitLab', 'Bitbucket', 'AzureDevOps'];
const PROVIDER = {
    GitHub: { repo: 'your-company/salesforce', repoHelp: 'owner/repo from the repository address: github.com/your-company/salesforce.',
        env: 'This org\'s environment in GitHub (Settings > Environments). It holds this org\'s login, and the pipeline uses it to send status back.',
        cred: 'RLY_GitHub', pipeline: 'Workflow file', pipelineDefault: 'release-relay.yml',
        pipelineHelp: 'File name in .github/workflows. It ships as release-relay.yml.' },
    GitLab: { repo: 'your-group/salesforce', repoHelp: 'The project path from its address: gitlab.com/your-group/salesforce.',
        env: 'GitLab environment name for this org (Operate > Environments).',
        cred: 'RLY_GitLab', pipeline: 'CI file', pipelineDefault: '.gitlab-ci.yml',
        pipelineHelp: 'The CI file that includes release-relay.gitlab-ci.yml. Usually .gitlab-ci.yml.' },
    Bitbucket: { repo: 'your-workspace/salesforce', repoHelp: 'workspace/repository from the address: bitbucket.org/your-workspace/salesforce.',
        env: 'Prefix of this org\'s repository variables, for example dev for DEV_SF_USERNAME.',
        cred: 'RLY_Bitbucket', pipeline: 'Custom pipeline', pipelineDefault: 'release-relay',
        pipelineHelp: 'Name of the custom pipeline in bitbucket-pipelines.yml. It ships as release-relay.' },
    AzureDevOps: { repo: 'your-org/Salesforce/salesforce', repoHelp: 'organization/project/repository from the address.',
        env: 'Suffix of this org\'s variable group: release-relay-dev holds the DEV login.',
        cred: 'RLY_AzureDevOps', pipeline: 'Pipeline id', pipelineDefault: '',
        pipelineHelp: 'The number after definitionId= in the pipeline\'s address.' }
};

function errorText(error) {
    if (!error) {
        return 'Something went wrong.';
    }
    if (error.body && error.body.message) {
        return error.body.message;
    }
    return error.message || JSON.stringify(error);
}

function typeLabel(t) {
    return TYPE_INFO[t] ? TYPE_INFO[t][0] : t;
}

function seg(list, active) {
    return list.map((o) => ({
        ...o,
        cls: 'rr-seg-btn' + (o.value === active ? ' on' : ''),
        pressed: o.value === active ? 'true' : 'false'
    }));
}

function formatWhen(value) {
    if (!value) {
        return '';
    }
    const d = new Date(value);
    const today = new Date();
    const sameDay = d.toDateString() === today.toDateString();
    const time = d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
    return sameDay ? 'Today ' + time : d.toLocaleDateString([], { month: 'short', day: 'numeric' });
}

export default class RlyReleaseApp extends LightningElement {
    typeOptions = TYPE_OPTIONS;
    typeChoices = DETECTABLE.map((t) => ({ label: typeLabel(t), value: t }));
    manualTypeOptions = MANUAL_TYPES.map((t) => ({ label: typeLabel(t), value: t }));
    manualChangeOptions = [
        { label: 'Add or update', value: 'Modified' },
        { label: 'Delete from the target', value: 'Deleted' }
    ];

    activeTab = 'new';
    step = 'connect';
    busy = false;

    // connect
    conn;
    target;
    connected = false;
    checking = false;
    checkMessage;
    connectError;
    connections = [];
    connectionsLoaded = false;
    connectionsError;
    connKey;

    // connections tab
    editing = false;
    adding = false;
    @track form = {};
    formError;
    savedNotice;

    // select
    mode = 'org';
    windowChoice = 'any';
    sinceDate;
    changedBy = 'me';
    searchTerm = '';
    typeSearch = '';
    typeFilter = 'All';
    statusFilter = 'All';
    showSame = false;
    shownLimit = PAGE_SIZE;
    @track changes = [];
    @track deletions = [];
    @track manualItems = [];
    @track selectedKeys = [];
    @track compared = {};      // key -> { status, added, removed }
    comparing = new Set();
    compareRunning = false;
    loadToken = 0;
    changesLoaded = false;
    deletionsLoaded = false;
    selectError;
    manualType = 'ApexClass';
    manualName = '';
    manualChange = 'Modified';
    branchOptions = [];
    existingBranch;
    comparison;
    expandedKey;
    previewLines = [];
    previewLoading = false;

    // review
    @track reviewItems = [];
    currentKey;
    currentPath;
    layout = 'split';
    reviewError;
    branchReviewed = false;
    deleteConfirmed = false;

    // raise
    branchName = '';
    branchTouched = false;
    title = '';
    description = '';
    raiseError;
    createdRequestId;

    connectedCallback() {
        this.loadConnections();
    }

    // ---------- tabs ----------

    handleTabActive(event) {
        this.activeTab = event.target.value;
    }

    goConnections() {
        this.activeTab = 'connections';
    }

    handleReleaseOpened() {
        this.activeTab = 'releases';
    }

    get isConnect() { return this.step === 'connect'; }
    get isSelect() { return this.step === 'select'; }
    get isReview() { return this.step === 'review'; }
    get isRaise() { return this.step === 'raise'; }

    get pathSteps() {
        const order = ['connect', 'select', 'review', 'raise'];
        const labels = { connect: 'Connect', select: 'Select', review: 'Review', raise: 'Raise' };
        const at = order.indexOf(this.step);
        return order.map((v, i) => ({
            value: v,
            label: (i < at ? '✓ ' : (i + 1) + ' ') + labels[v] + (v === 'select' && i < at && this.isOrgMode ? ' · ' + this.selectedKeys.length + ' items' : ''),
            cls: 'rr-path-step' + (i < at ? ' done' : i === at ? ' current' : ''),
            current: i === at ? 'step' : null
        }));
    }

    // ---------- connections ----------

    loadConnections() {
        this.busy = true;
        this.connectionsError = undefined;
        return getConnections()
            .then((list) => {
                this.connections = list || [];
                this.connectionsLoaded = true;
                // Connections still in the old custom metadata move to the Connection object once, for admins.
                if (this.connections.some((c) => c.isLegacy) && this.connections.some((c) => c.isAdmin)) {
                    return migrateConnections().then((n) => (n ? this.loadConnections() : null));
                }
                const keep = this.connections.find((c) => c.settingName === this.connKey);
                this.useConnection(keep || this.connections[0]);
                return null;
            })
            .catch((e) => {
                this.connectionsLoaded = true;
                this.connectionsError = errorText(e);
                this.connections = [];
            })
            .finally(() => {
                this.busy = false;
            });
    }

    useConnection(c) {
        this.conn = c;
        this.connKey = c ? c.settingName : undefined;
        if (!c) {
            return;
        }
        this.windowChoice = c.lookbackDays ? String(c.lookbackDays) : 'any';
        if (!['any', '7', '30'].includes(this.windowChoice)) {
            this.windowChoice = 'any';
        }
        if (!this.target || !c.targets.includes(this.target)) {
            this.target = c.targets.length ? c.targets[0] : undefined;
        }
        this.resetSelection();
        if (c.isGit) {
            this.handleTestConnection();
        }
    }

    get hasConnection() { return !!this.conn; }
    get noConnection() { return this.connectionsLoaded && !this.conn; }
    get isAdmin() { return this.connections.some((c) => c.isAdmin); }
    get isGitConn() { return !!this.conn && GIT_TYPES.includes(this.conn.connectionType); }
    get isDevOpsConn() { return !!this.conn && this.conn.connectionType === 'DevOpsCenter'; }
    get providerName() { return this.conn ? TYPE_LABEL[this.conn.connectionType] || this.conn.connectionType : ''; }
    get changeName() { return this.conn && this.conn.changeLabel ? this.conn.changeLabel : 'pull request'; }
    get targetOptions() { return this.conn ? this.conn.targets.map((t) => ({ label: t, value: t })) : []; }
    get showContinue() { return this.hasConnection && !this.isDevOpsConn; }
    get cantContinue() { return !this.connected || this.checking; }

    get connectionTiles() {
        return this.connections.map((c) => {
            const on = c.settingName === this.connKey;
            return {
                value: c.settingName,
                title: c.label,
                detail: c.connectionType === 'DevOpsCenter' ? 'Releases run in DevOps Center'
                    : 'Source → target via ' + (TYPE_LABEL[c.connectionType] || c.connectionType) + (c.codeScan === false ? ' · no code scan' : ' · code scan'),
                repo: c.repository || '',
                cls: 'rr-tile' + (on ? ' on' : ''),
                pressed: on ? 'true' : 'false'
            };
        });
    }

    handleConnectionTile(event) {
        const c = this.connections.find((x) => x.settingName === event.currentTarget.dataset.value);
        if (c && c.settingName !== this.connKey) {
            this.useConnection(c);
        }
    }

    handleTarget(event) {
        this.target = event.detail.value;
        this.resetSelection();
        this.handleTestConnection();
    }

    resetSelection() {
        this.connected = false;
        this.checkMessage = undefined;
        this.connectError = undefined;
        this.changes = [];
        this.changesLoaded = false;
        this.deletions = [];
        this.deletionsLoaded = false;
        this.selectedKeys = [];
        this.manualItems = [];
        this.compared = {};
        this.comparing = new Set();
        this.branchOptions = [];
        this.existingBranch = undefined;
        this.comparison = undefined;
        this.reviewItems = [];
    }

    // The connection is checked as soon as a connection and target are picked: no button to remember.
    handleTestConnection() {
        if (!this.target || !this.conn) {
            return;
        }
        this.checking = true;
        this.connectError = undefined;
        const key = this.connKey;
        const target = this.target;
        testConnection({ target, connection: key })
            .then((msg) => {
                if (key === this.connKey && target === this.target) {
                    this.connected = true;
                    this.checkMessage = msg;
                }
            })
            .catch((e) => {
                if (key === this.connKey && target === this.target) {
                    this.connected = false;
                    this.connectError = errorText(e);
                }
            })
            .finally(() => {
                this.checking = false;
            });
    }

    get checkText() {
        if (this.connected) {
            return '✓ Connection checked';
        }
        return this.connectError ? '✕ Connection problem' : '';
    }

    get checkClass() {
        return 'rr-check' + (this.connected ? ' ok' : this.connectError ? ' bad' : '');
    }

    get whatHappens() {
        if (!this.target) {
            return '';
        }
        const pair = ((this.conn && this.conn.deployEnvironments) || '').split(',').map((p) => p.trim().split('='))
            .find((p) => p.length === 2 && p[0] === this.target);
        const scan = this.conn && this.conn.codeScan === false ? '' : 'runs the code scan, ';
        return providerSentence(this.providerName, this.changeName, this.target, scan, !!pair);
    }

    // ---------- period and person ----------

    get windowButtons() {
        return seg([
            { label: 'Any time', value: 'any' },
            { label: 'Last 7 days', value: '7' },
            { label: 'Last 30 days', value: '30' },
            { label: 'Since a date…', value: 'since' }
        ], this.windowChoice);
    }

    get windowOptions() {
        return [
            { label: 'Any time', value: 'any' },
            { label: 'Last 7 days', value: '7' },
            { label: 'Last 30 days', value: '30' },
            { label: 'Last 90 days', value: '90' },
            { label: 'Since a date…', value: 'since' }
        ];
    }

    get changedByButtons() {
        return seg([{ label: 'Me', value: 'me' }, { label: 'Anyone', value: 'anyone' }], this.changedBy);
    }

    get isSinceDate() { return this.windowChoice === 'since'; }

    handleWindowPick(event) { this.windowChoice = event.currentTarget.dataset.value; }
    handleSinceDate(event) { this.sinceDate = event.target.value; }
    handleChangedByPick(event) { this.changedBy = event.currentTarget.dataset.value; }

    handleWindowReload(event) {
        this.windowChoice = event.detail.value;
        if (this.windowChoice !== 'since' || this.sinceDate) {
            this.loadChanges();
        }
    }

    handleSinceDateReload(event) {
        this.sinceDate = event.target.value;
        if (this.sinceDate) {
            this.loadChanges();
        }
    }

    handleChangedByReload(event) {
        this.changedBy = event.currentTarget.dataset.value;
        this.loadChanges();
    }

    /** Days for the server: 0 for any time. */
    get lookbackDays() {
        if (this.windowChoice === 'any') {
            return 0;
        }
        if (this.windowChoice === 'since') {
            if (!this.sinceDate) {
                return 0;
            }
            const days = Math.ceil((Date.now() - new Date(this.sinceDate + 'T00:00:00').getTime()) / 86400000);
            return Math.max(1, days);
        }
        return parseInt(this.windowChoice, 10) || 0;
    }

    goSelect() {
        if (!this.connected) {
            this.connectError = this.connectError || 'The connection hasn\'t been checked yet.';
            return;
        }
        this.step = 'select';
        if (this.mode === 'org' && !this.changesLoaded) {
            this.loadChanges();
        }
        if (this.mode === 'branch' && !this.branchOptions.length) {
            this.loadBranches();
        }
    }

    backToConnect() { this.step = 'connect'; }

    // ---------- select: mode ----------

    get modeButtons() {
        return seg([
            { label: 'Changes from this org', value: 'org' },
            { label: 'A branch already in ' + this.providerName, value: 'branch' }
        ], this.mode);
    }

    handleModePick(event) {
        this.mode = event.currentTarget.dataset.value;
        this.selectError = undefined;
        if (this.mode === 'branch' && !this.branchOptions.length) {
            this.loadBranches();
        }
        if (this.mode === 'org' && !this.changesLoaded) {
            this.loadChanges();
        }
    }

    get isOrgMode() { return this.mode === 'org'; }
    get isBranchMode() { return this.mode === 'branch'; }

    // ---------- select: loading and comparing ----------

    // The list shows as soon as it loads; the comparison with the target fills in a few rows at a time.
    loadChanges() {
        this.busy = true;
        this.selectError = undefined;
        const token = ++this.loadToken;
        getChanges({ lookbackDays: this.lookbackDays, changedBy: this.changedBy, nameSearch: null, target: this.target, connection: this.connKey })
            .then((rows) => {
                if (token !== this.loadToken) {
                    return;
                }
                const freshKeys = new Set(rows.map((r) => r.key));
                // Ticked rows from an earlier load stay, so switching Me / Anyone or the period never drops a pick.
                const keep = this.changes.filter((c) => this.selectedKeys.includes(c.key) && !freshKeys.has(c.key));
                this.changes = [...rows, ...keep];
                this.changesLoaded = true;
                this.shownLimit = PAGE_SIZE;
                this.compareShown();
            })
            .catch((e) => {
                this.selectError = errorText(e);
            })
            .finally(() => {
                this.busy = false;
            });
    }

    /** Compares the rows on screen that haven't been compared, in small batches. */
    compareShown() {
        if (this.compareRunning) {
            return;
        }
        const todo = this.pageItems
            .filter((r) => !r.deleted && !this.compared[r.key] && !this.comparing.has(r.key))
            .slice(0, COMPARE_BATCH);
        if (!todo.length) {
            return;
        }
        this.compareRunning = true;
        todo.forEach((r) => this.comparing.add(r.key));
        this.comparing = new Set(this.comparing);
        const token = this.loadToken;
        const payload = todo.map((r) => ({ key: r.key, metadataType: r.metadataType, name: r.name }));
        compareChanges({ itemsJson: JSON.stringify(payload), target: this.target, connection: this.connKey })
            .then((results) => {
                const next = { ...this.compared };
                results.forEach((c) => {
                    next[c.key] = { status: c.status, added: c.added, removed: c.removed };
                });
                todo.forEach((r) => {
                    if (!next[r.key]) {
                        next[r.key] = { status: 'Error' };
                    }
                });
                this.compared = next;
            })
            .catch(() => {
                const next = { ...this.compared };
                todo.forEach((r) => {
                    next[r.key] = { status: 'Error' };
                });
                this.compared = next;
            })
            .finally(() => {
                todo.forEach((r) => this.comparing.delete(r.key));
                this.comparing = new Set(this.comparing);
                this.compareRunning = false;
                if (token === this.loadToken) {
                    this.compareShown();
                }
            });
    }

    statusOf(item) {
        if (item.deleted) {
            return 'Deleted';
        }
        const c = this.compared[item.key];
        return c ? c.status : null;
    }

    /** Every listed item: changes, deletions and items added by name. */
    get allItems() {
        const manual = this.manualItems.map((m) => ({ ...m, manual: true, deleted: m.changeType === 'Deleted' }));
        const dels = this.deletions.map((d) => ({ ...d, deleted: true }));
        const seen = new Set();
        return [...manual, ...this.changes, ...dels].filter((i) => {
            if (seen.has(i.key)) {
                return false;
            }
            seen.add(i.key);
            return true;
        });
    }

    /** Items after the type, status, search and Same filters, before paging. */
    get filteredItems() {
        const term = this.searchTerm.trim().toLowerCase();
        return this.allItems.filter((i) => {
            const status = this.statusOf(i);
            if (this.typeFilter !== 'All' && i.metadataType !== this.typeFilter) {
                return false;
            }
            if (term && !i.name.toLowerCase().includes(term)) {
                return false;
            }
            if (this.statusFilter === 'All') {
                return this.showSame || status !== 'Same' || this.selectedKeys.includes(i.key);
            }
            if (this.statusFilter === 'Different') {
                return status === 'Different' || status === 'Exists';
            }
            return status === this.statusFilter;
        });
    }

    get pageItems() {
        return this.filteredItems.slice(0, this.shownLimit);
    }

    get pageRows() {
        const selected = new Set(this.selectedKeys);
        return this.pageItems.map((i) => {
            const status = this.statusOf(i);
            const info = STATUS[status] || null;
            const c = this.compared[i.key] || {};
            const expanded = this.expandedKey === i.key;
            return {
                key: i.key,
                previewKey: i.key + ':preview',
                name: i.name,
                typeLabel: typeLabel(i.metadataType),
                manual: i.manual,
                selected: selected.has(i.key),
                selectLabel: 'Select ' + i.name,
                comparing: !info && !i.deleted,
                badge: info ? info.label : 'Not compared',
                badgeCls: info ? info.cls : 'rr-badge rr-badge-same',
                badgeHelp: info ? info.help : '',
                hasDelta: status === 'Different' && (c.added || c.removed),
                added: c.added || 0,
                removed: c.removed || 0,
                when: i.deleted ? '' : formatWhen(i.lastModified),
                who: i.deleted ? i.lastModifiedByName : i.lastModifiedByName || '',
                canPreview: CODE_TYPES.includes(i.metadataType) && !i.deleted && (status === 'Different' || status === 'New'),
                expanded,
                previewIcon: expanded ? 'utility:chevrondown' : 'utility:chevronright',
                previewVariant: expanded ? 'brand' : 'border',
                rowCls: selected.has(i.key) ? 'rr-row-on' : ''
            };
        });
    }

    get noChanges() { return this.changesLoaded && this.filteredItems.length === 0; }
    get hasMore() { return this.filteredItems.length > this.shownLimit; }

    get pageSummary() {
        const total = this.filteredItems.length;
        const shown = Math.min(total, this.shownLimit);
        const left = this.pageItems.filter((r) => !r.deleted && !r.manual && !this.compared[r.key]).length;
        const hiddenSame = this.statusFilter === 'All' && !this.showSame
            ? this.allItems.filter((i) => this.statusOf(i) === 'Same' && !this.selectedKeys.includes(i.key)).length : 0;
        return 'Showing ' + (total ? '1–' + shown : '0') + ' of ' + total
            + (hiddenSame ? ' (' + hiddenSame + ' same as ' + this.target + ' hidden)' : '')
            + (left ? ' · comparing ' + left + ' more…' : '');
    }

    showMore() {
        this.shownLimit += PAGE_SIZE;
        this.compareShown();
    }

    // ---------- select: filters ----------

    get statTiles() {
        const items = this.allItems;
        const count = (s) => items.filter((i) => this.statusOf(i) === s).length;
        const tiles = [
            { value: 'All', label: 'All changes', count: items.length, hint: this.periodHint, accent: '' },
            { value: 'New', label: 'New (not in ' + this.target + ')', count: count('New'), hint: 'Will be created', accent: 'new' },
            { value: 'Different', label: 'Different from ' + this.target, count: count('Different') + count('Exists'), hint: 'Will overwrite it', accent: 'diff' },
            { value: 'Same', label: 'Same as ' + this.target, count: count('Same'), hint: 'Hidden unless shown', accent: 'same' },
            { value: 'Deleted', label: 'Only in ' + this.target, count: this.deletionsLoaded ? count('Deleted') : '–', hint: 'Possible deletions', accent: 'del' }
        ];
        return tiles.map((t) => ({
            ...t,
            cls: 'rr-stat rr-stat-' + (t.accent || 'all') + (this.statusFilter === t.value ? ' on' : ''),
            numCls: 'rr-stat-num rr-num-' + (t.accent || 'all'),
            pressed: this.statusFilter === t.value ? 'true' : 'false'
        }));
    }

    get periodHint() {
        const when = this.windowChoice === 'any' ? 'any time' : this.windowChoice === 'since' ? 'since ' + (this.sinceDate || '…') : 'last ' + this.windowChoice + ' days';
        return when + ' · ' + (this.changedBy === 'me' ? 'me' : 'anyone');
    }

    handleStatPick(event) {
        this.statusFilter = event.currentTarget.dataset.value;
        if (this.statusFilter === 'Deleted' && !this.deletionsLoaded) {
            this.loadDeletions();
        }
        this.shownLimit = PAGE_SIZE;
        this.compareShown();
    }

    get typeNav() {
        const counts = new Map();
        this.allItems.forEach((i) => counts.set(i.metadataType, (counts.get(i.metadataType) || 0) + 1));
        const term = this.typeSearch.trim().toLowerCase();
        const out = [{ key: 'all', value: 'All', label: 'All types', count: this.allItems.length,
            cls: 'rr-type' + (this.typeFilter === 'All' ? ' on' : ''), pressed: this.typeFilter === 'All' ? 'true' : 'false' }];
        GROUP_ORDER.forEach((g) => {
            const types = [...counts.keys()].filter((t) => (TYPE_INFO[t] ? TYPE_INFO[t][1] : 'Other') === g)
                .filter((t) => !term || typeLabel(t).toLowerCase().includes(term))
                .sort((a, b) => typeLabel(a).localeCompare(typeLabel(b)));
            if (!types.length) {
                return;
            }
            out.push({ key: 'g-' + g, isGroup: true, label: g });
            types.forEach((t) => out.push({
                key: 't-' + t, value: t, label: typeLabel(t), count: counts.get(t),
                cls: 'rr-type' + (this.typeFilter === t ? ' on' : ''), pressed: this.typeFilter === t ? 'true' : 'false'
            }));
        });
        return out;
    }

    handleTypePick(event) {
        this.typeFilter = event.currentTarget.dataset.value;
        this.shownLimit = PAGE_SIZE;
        this.compareShown();
    }

    handleTypeSearch(event) { this.typeSearch = event.target.value || ''; }

    handleSearch(event) {
        this.searchTerm = event.target.value || '';
        this.shownLimit = PAGE_SIZE;
        this.compareShown();
    }

    handleShowSame(event) {
        this.showSame = event.target.checked;
    }

    // ---------- select: picking ----------

    get newCount() { return this.allItems.filter((i) => this.statusOf(i) === 'New').length; }
    get differentCount() { return this.allItems.filter((i) => ['Different', 'Exists'].includes(this.statusOf(i))).length; }

    addKeys(keys) {
        const set = new Set(this.selectedKeys);
        keys.forEach((k) => set.add(k));
        this.selectedKeys = [...set];
        this.selectError = undefined;
    }

    selectAllNew() { this.addKeys(this.allItems.filter((i) => this.statusOf(i) === 'New').map((i) => i.key)); }
    selectAllDifferent() { this.addKeys(this.allItems.filter((i) => ['Different', 'Exists'].includes(this.statusOf(i))).map((i) => i.key)); }
    selectPage() { this.addKeys(this.pageItems.map((i) => i.key)); }

    get allShownSelected() {
        const page = this.pageItems;
        return page.length > 0 && page.every((i) => this.selectedKeys.includes(i.key));
    }

    handleSelectShown(event) {
        const keys = this.pageItems.map((i) => i.key);
        if (event.target.checked) {
            this.addKeys(keys);
        } else {
            const drop = new Set(keys);
            this.selectedKeys = this.selectedKeys.filter((k) => !drop.has(k));
        }
    }

    handleRowCheck(event) {
        const key = event.target.dataset.key;
        if (event.target.checked) {
            this.addKeys([key]);
        } else {
            this.selectedKeys = this.selectedKeys.filter((k) => k !== key);
        }
    }

    removeSelected(event) {
        const key = event.currentTarget.dataset.key;
        this.selectedKeys = this.selectedKeys.filter((k) => k !== key);
        this.manualItems = this.manualItems.filter((m) => m.key !== key);
    }

    clearSelection() {
        this.selectedKeys = [];
        this.manualItems = [];
        this.deleteConfirmed = false;
    }

    findItem(key) {
        return this.allItems.find((i) => i.key === key);
    }

    get selectedCount() { return this.selectedKeys.length; }
    get noneSelected() { return this.selectedKeys.length === 0; }
    get selectedItems() { return this.selectedKeys.map((k) => this.findItem(k)).filter((i) => i); }
    get basketNew() { return this.selectedItems.filter((i) => this.statusOf(i) === 'New').length; }
    get basketDeleted() { return this.selectedItems.filter((i) => i.deleted).length; }
    get basketChanged() { return this.selectedItems.length - this.basketNew - this.basketDeleted; }
    get reviewButtonLabel() { return this.selectedKeys.length ? 'Next: Review ' + this.selectedKeys.length + (this.selectedKeys.length === 1 ? ' item' : ' items') : 'Next: Review'; }

    get basketGroups() {
        const groups = new Map();
        this.selectedItems.forEach((i) => {
            if (!groups.has(i.metadataType)) {
                groups.set(i.metadataType, []);
            }
            groups.get(i.metadataType).push({ key: i.key, name: i.name });
        });
        return [...groups.entries()].map(([type, items]) => ({ type, label: typeLabel(type), items }));
    }

    /** A test class for each picked Apex class that isn't picked yet: validation needs it. */
    get suggestions() {
        const picked = new Set(this.selectedItems.map((i) => i.key.toLowerCase()));
        const classes = this.allItems.filter((i) => i.metadataType === 'ApexClass');
        const out = [];
        this.selectedItems
            .filter((i) => i.metadataType === 'ApexClass' && !i.deleted && !/test$/i.test(i.name))
            .forEach((i) => {
                const test = classes.find((c) => [i.name + 'test', i.name + '_test'].includes(c.name.toLowerCase()));
                if (test && !picked.has(test.key.toLowerCase())) {
                    out.push({ key: test.key, name: test.name, forName: i.name });
                }
            });
        return out.slice(0, 3);
    }

    addSuggestion(event) {
        this.addKeys([event.currentTarget.dataset.key]);
    }

    // ---------- select: deletions and items added by name ----------

    loadDeletions() {
        this.busy = true;
        this.selectError = undefined;
        getDeletions({ target: this.target, connection: this.connKey })
            .then((rows) => {
                this.deletions = rows;
                this.deletionsLoaded = true;
            })
            .catch((e) => {
                this.selectError = errorText(e);
            })
            .finally(() => {
                this.busy = false;
            });
    }

    get deletionsNote() {
        return this.deletions.length
            ? this.deletions.length + ' only in ' + this.target + '. Pick them from the "Only in ' + this.target + '" tile.'
            : 'Nothing to delete: everything in ' + this.target + ' still exists here.';
    }

    get needsDeleteConfirm() { return this.basketDeleted > 0; }

    get deleteConfirmLabel() {
        const n = this.basketDeleted;
        return 'I deleted ' + (n === 1 ? 'this component' : 'these ' + n + ' components') + ' in this org on purpose';
    }

    handleDeleteConfirm(event) {
        this.deleteConfirmed = event.target.checked;
        this.selectError = undefined;
    }

    handleManualType(event) { this.manualType = event.detail.value; }
    handleManualName(event) { this.manualName = event.target.value; }
    handleManualChange(event) { this.manualChange = event.detail.value; }

    addManual() {
        const name = (this.manualName || '').trim();
        if (!name || /[,:\r\n]/.test(name)) {
            this.selectError = 'Enter the API name without commas or colons, for example Account.Region__c for a field.';
            return;
        }
        const key = this.manualType + ':' + name;
        this.manualItems = [...this.manualItems.filter((m) => m.key !== key), {
            key, metadataType: this.manualType, name, changeType: this.manualChange, source: 'Manual',
            lastModifiedByName: 'Added by name'
        }];
        this.addKeys([key]);
        this.manualName = '';
        if (this.manualChange !== 'Deleted') {
            this.compareShown();
        }
    }

    // ---------- select: quick look ----------

    handlePreview(event) {
        const key = event.currentTarget.dataset.key;
        if (this.expandedKey === key) {
            this.expandedKey = undefined;
            return;
        }
        const item = this.findItem(key);
        this.expandedKey = key;
        this.previewLines = [];
        this.previewLoading = true;
        getSources({ metadataType: item.metadataType, componentName: item.name, target: this.target, connection: this.connKey })
            .then((files) => {
                const lines = [];
                files.filter((f) => !f.path.endsWith('-meta.xml')).forEach((f) => {
                    const d = buildDiff(f.branchSource, f.orgSource);
                    d.lines.filter((l) => l.kind !== 'same' || l.kind === 'gap').slice(0, 40)
                        .forEach((l) => lines.push({ ...l, id: f.path + l.id }));
                });
                if (this.expandedKey === key) {
                    this.previewLines = lines.length ? lines : [{ id: 'none', cls: 'line gap', sign: '', text: 'No line changes.' }];
                }
            })
            .catch((e) => {
                this.previewLines = [{ id: 'err', cls: 'line gap', sign: '', text: errorText(e) }];
            })
            .finally(() => {
                this.previewLoading = false;
            });
    }

    // ---------- select: existing branch ----------

    loadBranches() {
        this.busy = true;
        getBranches({ connection: this.connKey })
            .then((rows) => {
                this.branchOptions = rows.map((b) => ({ label: b, value: b }));
            })
            .catch((e) => {
                this.selectError = errorText(e);
            })
            .finally(() => {
                this.busy = false;
            });
    }

    get noBranches() { return this.isBranchMode && !this.busy && this.branchOptions.length === 0; }

    handleExistingBranch(event) {
        this.existingBranch = event.detail.value;
        this.comparison = undefined;
        this.branchReviewed = false;
        this.selectError = undefined;
    }

    // ---------- to review ----------

    goReview() {
        if (this.mode === 'branch') {
            if (!this.existingBranch) {
                this.selectError = 'Pick the branch to raise a pull request from.';
                return;
            }
            this.busy = true;
            compareBranch({ branch: this.existingBranch, target: this.target, connection: this.connKey })
                .then((c) => {
                    if (!c.aheadBy) {
                        this.selectError = this.existingBranch + ' has no commits that aren\'t already in ' + this.target + '.';
                        return;
                    }
                    this.comparison = { ...c, fileRows: c.files.map((f, i) => ({ id: 'f' + i, text: f })) };
                    this.branchName = this.existingBranch;
                    this.step = 'review';
                })
                .catch((e) => {
                    this.selectError = errorText(e);
                })
                .finally(() => {
                    this.busy = false;
                });
            return;
        }
        if (!this.selectedKeys.length) {
            this.selectError = 'Select at least one change, deletion, or item added by name.';
            return;
        }
        if (this.needsDeleteConfirm && !this.deleteConfirmed) {
            this.selectError = 'Confirm the deletions are ones you made in this org.';
            return;
        }
        const previous = new Map(this.reviewItems.map((r) => [r.key, r]));
        this.reviewItems = this.selectedItems.map((c) => {
            if (previous.has(c.key)) {
                return { ...previous.get(c.key), status: this.statusOf(c) };
            }
            return {
                key: c.key, metadataType: c.metadataType, name: c.name, source: c.manual ? 'Manual' : 'Detected',
                status: this.statusOf(c), reviewed: false, loaded: false, files: [],
                isDeleted: !!c.deleted, isCode: !c.deleted && CODE_TYPES.includes(c.metadataType)
            };
        });
        this.step = 'review';
        this.openItem(this.reviewItems[0].key);
    }

    // ---------- review ----------

    changeTypeOf(r) {
        if (r.isDeleted) {
            return 'Deleted';
        }
        return r.status === 'New' ? 'New' : 'Modified';
    }

    badgeFor(r) {
        if (r.isDeleted) {
            return STATUS.Deleted;
        }
        return STATUS[r.status] || { label: 'Changed', cls: 'rr-badge rr-badge-exists' };
    }

    get reviewList() {
        return this.reviewItems.map((r) => ({
            ...r,
            cls: 'rr-review-item' + (r.key === this.currentKey ? ' current' : ''),
            icon: r.reviewed ? 'utility:success' : r.isDeleted ? 'utility:delete' : 'utility:record',
            iconCls: r.reviewed ? 'rr-icon-ok' : '',
            caption: typeLabel(r.metadataType) + ' · ' + this.badgeFor(r).label + (r.source === 'Manual' ? ' · added by name' : '')
        }));
    }

    get current() {
        const r = this.reviewItems.find((x) => x.key === this.currentKey);
        if (!r) {
            return null;
        }
        const badge = this.badgeFor(r);
        return { ...r, typeLabel: typeLabel(r.metadataType), badgeText: badge.label, badgeCls: badge.cls };
    }

    get reviewedCount() { return this.reviewItems.filter((r) => r.reviewed).length; }
    get summaryCount() { return this.reviewItems.length; }
    get deleteCount() { return this.reviewItems.filter((r) => r.isDeleted).length; }
    get progressStyle() { return 'width:' + (this.summaryCount ? Math.round((this.reviewedCount * 100) / this.summaryCount) : 0) + '%'; }
    get currentLoading() { return this.current && this.current.isCode && !this.current.loaded; }
    get currentXml() { return this.current && !this.current.isCode && !this.current.isDeleted; }
    get currentDeleted() { return this.current && this.current.isDeleted; }
    get currentNoFiles() { return this.current && this.current.isCode && this.current.loaded && !this.current.files.length; }
    get hasCurrentFiles() { return this.current && this.current.files && this.current.files.length > 0; }

    get currentFileTabs() {
        return (this.current ? this.current.files : []).map((f) => ({
            path: f.path,
            short: f.path.split('/').pop(),
            stats: f.stats,
            cls: 'rr-file-tab' + (f.path === this.currentPath ? ' on' : ''),
            selected: f.path === this.currentPath ? 'true' : 'false'
        }));
    }

    get currentFile() {
        return this.current ? this.current.files.find((f) => f.path === this.currentPath) : null;
    }

    get layoutButtons() {
        return seg([{ label: 'Side by side', value: 'split' }, { label: 'Unified', value: 'unified' }], this.layout);
    }

    get isSideBySide() { return this.layout === 'split'; }

    handleLayout(event) { this.layout = event.currentTarget.dataset.value; }
    handleFileTab(event) { this.currentPath = event.currentTarget.dataset.path; }
    handleOpenItem(event) { this.openItem(event.currentTarget.dataset.key); }

    openItem(key) {
        this.currentKey = key;
        const item = this.reviewItems.find((r) => r.key === key);
        this.currentPath = item && item.files.length ? item.files[0].path : undefined;
        if (!item || !item.isCode || item.loaded) {
            return;
        }
        getSources({ metadataType: item.metadataType, componentName: item.name, target: this.target, connection: this.connKey })
            .then((files) => {
                const built = files.map((f) => {
                    const d = buildDiff(f.branchSource, f.orgSource);
                    return {
                        path: f.path,
                        stats: f.inBranch ? '+' + d.added + ' −' + d.removed : 'new file',
                        lines: d.lines,
                        rows: sideBySide(d.lines).map((r) => ({ ...r, leftKey: r.id + 'L', rightKey: r.id + 'R' }))
                    };
                });
                const status = item.status || (built.length && built.every((f) => f.stats === 'new file') ? 'New' : 'Different');
                this.updateItem(key, { files: built, loaded: true, status });
                if (this.currentKey === key && built.length) {
                    this.currentPath = built[0].path;
                }
            })
            .catch((e) => {
                this.reviewError = errorText(e);
                this.updateItem(key, { loaded: true });
            });
    }

    updateItem(key, patch) {
        this.reviewItems = this.reviewItems.map((r) => (r.key === key ? { ...r, ...patch } : r));
    }

    get reviewedLabel() { return this.current && this.current.reviewed ? 'Reviewed' : 'Mark reviewed'; }
    get reviewedVariant() { return this.current && this.current.reviewed ? 'success' : 'brand'; }
    get reviewedIcon() { return this.current && this.current.reviewed ? 'utility:check' : ''; }

    toggleReviewed() {
        const key = this.currentKey;
        const now = !(this.current && this.current.reviewed);
        this.updateItem(key, { reviewed: now });
        this.reviewError = undefined;
        if (now) {
            const next = this.reviewItems.find((r) => !r.reviewed);
            if (next) {
                this.openItem(next.key);
            }
        }
    }

    handleBranchReviewed(event) {
        this.branchReviewed = event.target.checked;
        this.reviewError = undefined;
    }

    goRaise() {
        if (this.mode === 'branch') {
            if (!this.branchReviewed) {
                this.reviewError = 'Confirm you\'ve reviewed the changes in ' + this.providerName + ' first.';
                return;
            }
            if (!this.title) {
                this.title = this.existingBranch.split('/').pop().replace(/[-_.]+/g, ' ');
            }
            this.step = 'raise';
            return;
        }
        const left = this.reviewItems.filter((r) => !r.reviewed);
        if (left.length) {
            this.reviewError = 'Mark these as reviewed first: ' + left.map((r) => r.name).join(', ');
            return;
        }
        if (!this.description) {
            const line = (r) => '- ' + typeLabel(r.metadataType) + ': ' + r.name + ' (' + this.badgeFor(r).label.toLowerCase() + ')';
            const adds = this.reviewItems.filter((r) => !r.isDeleted).map(line);
            const dels = this.reviewItems.filter((r) => r.isDeleted).map(line);
            this.description = (adds.length ? 'Added or updated:\n' + adds.join('\n') + '\n\n' : '')
                + (dels.length ? 'Deleted:\n' + dels.join('\n') + '\n\n' : '')
                + 'All items reviewed in Release Relay (' + (this.conn ? this.conn.orgLabel : '') + ').';
        }
        if (!this.branchName) {
            this.branchName = 'feature/';
        }
        this.step = 'raise';
    }

    backToSelect() { this.step = 'select'; }
    backToReview() { this.step = 'review'; }

    // ---------- raise ----------

    get branchLocked() { return this.mode === 'branch'; }
    get raiseButtonLabel() { return 'Create ' + this.changeName; }

    get requestType() {
        if (this.mode === 'branch') {
            return 'Manual PR';
        }
        const dels = this.deleteCount;
        const changes = this.summaryCount - dels;
        return dels ? (changes ? 'Changes and destructive' : 'Destructive') : 'Changes';
    }

    get requestTypeDetail() {
        if (this.mode === 'branch') {
            return 'From ' + this.existingBranch + '; nothing is retrieved from this org';
        }
        const dels = this.deleteCount;
        const fresh = this.reviewItems.filter((r) => r.status === 'New' && !r.isDeleted).length;
        return this.summaryCount + ' · ' + fresh + ' new, ' + (this.summaryCount - dels - fresh) + ' changed, ' + dels + ' deleted';
    }

    get requestTypeClass() {
        return 'type-badge type-' + this.requestType.toLowerCase().replace(/ /g, '-');
    }

    get afterRaising() {
        const scan = this.conn && this.conn.codeScan === false ? '' : 'Code scan, then ';
        return scan + 'validation in ' + this.target + ', then approval';
    }

    get raisedText() {
        return 'The ' + this.changeName + ' opens in ' + this.providerName + ' in a minute or two. The release page updates by itself as each step finishes.';
    }

    handleBranch(event) {
        this.branchName = event.target.value.trim();
        this.branchTouched = true;
    }

    // The branch name follows the title until it's edited by hand.
    handleTitle(event) {
        this.title = event.target.value;
        if (!this.branchTouched && this.mode === 'org') {
            const slug = (this.title || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);
            this.branchName = 'feature/' + slug;
        }
    }

    handleDescription(event) { this.description = event.target.value; }

    handleRaise() {
        if (!this.title || !this.title.trim()) {
            this.raiseError = 'Enter a title for the release.';
            return;
        }
        if (this.isGitConn && !BRANCH_RE.test(this.branchName)) {
            this.raiseError = 'Branch must look like feature/short-name (or bugfix/, hotfix/), using lowercase letters, numbers, dots and dashes.';
            return;
        }
        this.busy = true;
        this.raiseError = undefined;
        const items = this.mode === 'org'
            ? this.reviewItems.map((r) => ({
                metadataType: r.metadataType, name: r.name, changeType: this.changeTypeOf(r), source: r.source, reviewed: r.reviewed
            }))
            : [];
        raiseRequest({
            mode: this.mode,
            title: this.title.trim(),
            description: this.description,
            branchName: this.branchName,
            target: this.target,
            itemsJson: JSON.stringify(items),
            connection: this.connKey
        })
            .then((id) => {
                this.createdRequestId = id;
                // Saved; now start the pipeline in a second short call (callouts can't follow the save).
                return startPipeline({ requestId: id }).catch(() => null);
            })
            .then(() => {
                this.dispatchEvent(new ShowToastEvent({ title: 'Release raised', message: this.raisedText, variant: 'success' }));
                const list = this.template.querySelector('c-rly-release-list');
                if (list) {
                    list.refresh();
                }
            })
            .catch((e) => {
                this.raiseError = errorText(e);
            })
            .finally(() => {
                this.busy = false;
            });
    }

    viewRequest() {
        const list = this.template.querySelector('c-rly-release-list');
        this.activeTab = 'releases';
        if (list) {
            list.openRelease(this.createdRequestId);
        }
    }

    startOver() {
        this.selectedKeys = [];
        this.manualItems = [];
        this.reviewItems = [];
        this.currentKey = undefined;
        this.existingBranch = undefined;
        this.comparison = undefined;
        this.branchReviewed = false;
        this.deleteConfirmed = false;
        this.branchName = '';
        this.branchTouched = false;
        this.title = '';
        this.description = '';
        this.createdRequestId = undefined;
        this.step = 'select';
        if (this.mode === 'org') {
            this.loadChanges();
        }
    }

    // ---------- connections tab ----------

    get connectionCards() {
        return this.connections.map((c) => ({
            ...c,
            typeLabel: TYPE_LABEL[c.connectionType] || c.connectionType,
            targetList: (c.targets || []).join(', '),
            scanLabel: c.codeScan === false ? 'Off' : 'On',
            periodLabel: c.lookbackDays ? 'Last ' + c.lookbackDays + ' days' : 'Any time'
        }));
    }

    get formIsGit() { return GIT_TYPES.includes(this.form.type); }
    get formIsDevOps() { return this.form.type === 'DevOpsCenter'; }
    get formNeedsTypes() { return !this.formIsDevOps; }
    get formTypeLocked() { return !this.adding; }
    get formProvider() { return PROVIDER[this.form.type] || PROVIDER.GitHub; }
    get repoPlaceholder() { return this.formProvider.repo; }
    get repoHelp() { return this.formProvider.repoHelp; }
    get envHelp() { return this.formProvider.env; }
    get credentialPlaceholder() { return this.formProvider.cred; }
    get pipelineLabel() { return this.formProvider.pipeline; }
    get pipelinePlaceholder() { return this.formProvider.pipelineDefault || '12'; }
    get pipelineHelp() { return this.formProvider.pipelineHelp; }
    get formTitle() { return this.adding ? 'New connection for this org' : 'Edit connection'; }
    get secretNote() {
        if (this.formIsDevOps) {
            return 'DevOps Center keeps its own connection to your Git provider.';
        }
        return 'The token is set by an admin in Setup > Named Credentials > ' + (this.form.namedCredential || this.credentialPlaceholder) + ', never on this page.';
    }

    handleFormType(event) {
        const type = event.detail.value;
        const p = PROVIDER[type];
        this.form = { ...this.form, type, workflowFile: p ? p.pipelineDefault : '', namedCredential: '' };
        this.formError = undefined;
    }

    startEditFor(event) {
        const c = this.connections.find((x) => x.settingName === event.currentTarget.dataset.key);
        if (c) {
            this.startEdit(c);
        }
    }

    startEdit(c) {
        this.form = {
            settingName: c.settingName, isLegacy: c.isLegacy, label: c.label, type: c.connectionType,
            namedCredential: c.namedCredential || '', devopsUrl: c.devopsUrl || '', devopsProject: c.devopsProject || '',
            devopsPipeline: c.devopsPipeline || '', deployEnvironments: c.deployEnvironments || '',
            allowSelfApproval: c.allowSelfApproval === true, codeScan: c.codeScan !== false,
            orgLabel: c.orgLabel, repository: c.repository, environment: c.environment,
            targets: c.targets.join(', '), workflowFile: c.workflowFile, workflowRef: c.workflowRef,
            sourcePath: c.sourcePath, lookbackDays: c.lookbackDays || '',
            metadataTypes: c.metadataTypes.filter((t) => DETECTABLE.includes(t))
        };
        this.formError = undefined;
        this.adding = false;
        this.editing = true;
        this.savedNotice = undefined;
    }

    startAddFromConnect() {
        this.activeTab = 'connections';
        this.startAdd();
    }

    startAdd() {
        const c = this.conn || {};
        this.form = {
            settingName: null, label: '', type: 'GitHub', namedCredential: '', deployEnvironments: '', allowSelfApproval: false,
            codeScan: true, devopsUrl: '', devopsProject: '', devopsPipeline: '',
            orgLabel: c.orgLabel || '', repository: '', environment: c.environment || '',
            targets: (c.targets || []).join(', '), workflowFile: 'release-relay.yml', workflowRef: 'main',
            sourcePath: 'force-app/main/default', lookbackDays: '',
            metadataTypes: [...DETECTABLE]
        };
        this.formError = undefined;
        this.adding = true;
        this.editing = true;
        this.savedNotice = undefined;
    }

    handleFormCheck(event) {
        this.form = { ...this.form, [event.target.dataset.field]: event.target.checked };
    }

    cancelEdit() {
        this.editing = false;
        this.adding = false;
    }

    handleForm(event) {
        this.form = { ...this.form, [event.target.dataset.field]: event.target.value };
        this.formError = undefined;
    }

    handleTypes(event) {
        this.form = { ...this.form, metadataTypes: event.detail.value };
        this.formError = undefined;
    }

    saveEdit() {
        const f = this.form;
        const split = (v) => (v || '').split(',').map((s) => s.trim()).filter((s) => s);
        const isGit = GIT_TYPES.includes(f.type);
        if (isGit && !(f.repository || '').trim()) {
            this.formError = 'Repository is required, as ' + this.repoPlaceholder + '.';
            return;
        }
        if (f.type === 'DevOpsCenter' && !(f.devopsUrl || '').startsWith('https://')) {
            this.formError = 'DevOps Center link must start https://.';
            return;
        }
        if (f.type !== 'DevOpsCenter' && (!f.metadataTypes || !f.metadataTypes.length)) {
            this.formError = 'Pick at least one type to detect.';
            return;
        }
        if (!split(f.targets).length) {
            this.formError = 'Add at least one target, for example sit.';
            return;
        }
        if (this.adding && !(f.label || '').trim()) {
            this.formError = 'Give the new connection a name.';
            return;
        }
        const days = parseInt(f.lookbackDays, 10);
        const payload = {
            settingName: this.adding ? null : f.settingName,
            isLegacy: this.adding ? false : f.isLegacy === true,
            label: (f.label || '').trim(),
            deployEnvironments: (f.deployEnvironments || '').replace(/\s/g, ''),
            allowSelfApproval: f.allowSelfApproval === true,
            codeScan: f.codeScan !== false,
            connectionType: f.type, namedCredential: (f.namedCredential || '').trim(),
            devopsUrl: (f.devopsUrl || '').trim(), devopsProject: (f.devopsProject || '').trim(),
            devopsPipeline: (f.devopsPipeline || '').trim(),
            orgLabel: (f.orgLabel || '').trim(), repository: (f.repository || '').trim(), environment: (f.environment || '').trim(),
            targets: split(f.targets), workflowFile: (f.workflowFile || '').trim(), workflowRef: (f.workflowRef || '').trim(),
            sourcePath: (f.sourcePath || '').trim(), metadataTypes: [...(f.metadataTypes || [])],
            lookbackDays: Number.isNaN(days) ? null : days
        };
        this.busy = true;
        saveConnection({ connectionJson: JSON.stringify(payload) })
            .then((key) => {
                this.editing = false;
                this.adding = false;
                this.connKey = key;
                this.savedNotice = 'Connection saved.';
                return this.loadConnections();
            })
            .catch((e) => {
                this.formError = errorText(e);
            })
            .finally(() => {
                this.busy = false;
            });
    }
}

function providerSentence(provider, changeName, target, scan, deploys) {
    return provider + ': opens a ' + changeName + ' from a new branch into ' + target + ', ' + scan
        + (deploys ? 'validates it against the ' + target + ' org and waits for approval. Approving merges and deploys it.'
            : 'and waits for approval. Approving merges it (Git only: nothing is deployed for this target).');
}
